struct PanelQuad4;

struct PanelQuad4VTable {
    char padding0[24];
    short turn_on_adjustment;
    short turn_on_zero;
    void (*turn_on)(void *, bool);
    char padding1[16];
    short rotate_adjustment;
    short rotate_zero;
    void (*rotate)(void *, float, float, float);
    char padding2[48];
    short is_on_adjustment;
    short is_on_zero;
    bool (*is_on)(void *);
};

struct PanelQuad4 {
    char padding[404];
    PanelQuad4VTable *vtable;

    void TurnOn(bool enabled)
    {
        vtable->turn_on((char *)this + vtable->turn_on_adjustment, enabled);
    }

    void Rotate(float x, float y, float rotation)
    {
        vtable->rotate(
            (char *)this + vtable->rotate_adjustment,
            x,
            y,
            rotation
        );
    }

    bool IsOn()
    {
        return vtable->is_on((char *)this + vtable->is_on_adjustment);
    }
};

class FanMeterWidget {
public:
    int display;
    void *vtable;
    int numSections;
    PanelQuad4 **sectionPQs;
    void *arrowPQ;
    float size;
    int centerX;
    int centerY;

    void SetSize(float f);
};

void FanMeterWidget::SetSize(const float f)
{
    float pos = 0.0, dt = 0.0f;
    int numHoles;
    int dest = (numSections % 2 == 0)
        ? (numSections / 2 - 1)
        : (numSections / 2);
    int i, j;

    for (i = 0; i < numSections; i++)
        sectionPQs[i]->TurnOn(false);

    if (f > 0.0f)
        dt = 1.0f / f;

    while (dt > 0.0f && int(pos) <= dest)
    {
        sectionPQs[int(pos)]->TurnOn(true);
        pos += dt;
    }
    for (i = numSections - 1; i > dest; i--)
    {
        sectionPQs[i]->TurnOn(sectionPQs[numSections - 1 - i]->IsOn());
    }

    for (i = 0; i < numSections / 2; i++)
    {
        numHoles = 0;
        for (j = i + 1; j < numSections / 2; j++)
        {
            if (!sectionPQs[j]->IsOn())
                numHoles++;
        }

        sectionPQs[i]->Rotate(
            centerX,
            centerY,
            float(numHoles) * (3.14159274101257324219f / float(numSections))
        );
    }

    for (i = numSections - 1; i >= numSections / 2; i--)
    {
        numHoles = 0;
        for (j = i - 1; j >= numSections / 2; j--)
        {
            if (!sectionPQs[j]->IsOn())
                numHoles++;
        }

        sectionPQs[i]->Rotate(
            centerX,
            centerY,
            float(numHoles) * (-3.14159274101257324219f / float(numSections))
        );
    }

    size = f;
}
